python3 << 'EOF'
import zipfile
import xml.etree.ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
z = zipfile.ZipFile('budget.xlsx')

# Shared strings (if any)
shared = []
try:
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall(f'{M}si'):
        shared.append(''.join(t.text or '' for t in si.iter(f'{M}t')))
except KeyError:
    pass

root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

def col_letter(ref):
    return ''.join(ch for ch in ref if ch.isalpha())

rows = {}
for row in root.findall(f'.//{M}row'):
    r = int(row.get('r'))
    for c in row.findall(f'{M}c'):
        ref = c.get('r')
        t = c.get('t')
        v = c.find(f'{M}v')
        val = v.text if v is not None else None
        if t == 's' and val is not None:
            val = shared[int(val)]
        elif t == 'inlineStr':
            is_el = c.find(f'{M}is')
            val = ''.join(tt.text or '' for tt in is_el.iter(f'{M}t')) if is_el is not None else ''
        elif t == 'str':
            val = val
        rows.setdefault(r, {})[col_letter(ref)] = val

for r in sorted(rows):
    print(r, rows[r])
EOF
